{
  "name": "@amykit/plugin-file-store",
  "version": "0.6.0",
  "description": "Work records kept as one file per item.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/file-store"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "@amykit/plugin-file-brief-store": "^0.6.0"
  }
}

import fs from "node:fs";
import path from "node:path";
import { Store } from "@amykit/core";
import { WorkRecord } from "@amykit/core";

/** One file per ticket, so a record can be read and edited by hand. */
export class FileStore<R extends WorkRecord = WorkRecord> implements Store<R> {
  constructor(private readonly root: string, create = true) {
    if (create) fs.mkdirSync(this.root, { recursive: true });
  }

  load(workId: string): R | null {
    const file = this.file(workId);
    if (!fs.existsSync(file)) return null;
    return JSON.parse(fs.readFileSync(file, "utf-8")) as R;
  }

  save(record: R): void {
    // Written to a sibling and renamed, so a crash mid-write cannot leave a
    // half-written record that fails to parse on the next look.
    const file = this.file(record.id);

    const temporary = `${file}.tmp`;
    fs.writeFileSync(temporary, JSON.stringify(record, null, 2), "utf-8");
    fs.renameSync(temporary, file);
  }

  all(): R[] {
    if (!fs.existsSync(this.root)) return [];
    return fs
      .readdirSync(this.root)
      .filter((name) => name.endsWith(".json"))
      .map((name) => JSON.parse(fs.readFileSync(path.join(this.root, name), "utf-8")) as R);
  }

  private file(workId: string): string {
    return path.join(this.root, `${workId}.json`);
  }
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  directory: {
    type: "string",
    description:
      "where the records are kept, relative to the state directory. One per workflow, so two profiles under one `.amy` do not read each other's work",
    default: "tickets",
  },
  briefsDirectory: {
    type: "string",
    description:
      "deprecated: where briefs are kept, translated to @amykit/plugin-file-brief-store so existing installs keep their briefs",
  },
} satisfies ConfigSchema;

// Kept as a type-level and runtime import for adapters built before briefs
// became their own mount; the plugin itself now mounts records only.
export { FileBriefStore } from "@amykit/plugin-file-brief-store";
export { FileStore } from "./FileStore.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import path from "node:path";
import { definePlugin } from "@amykit/core";
import { FileStore } from "./FileStore.js";
import { configSchema } from "./config.js";

/** The record store only; briefs mount through their own adapter. */
export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-file-store",
  configSchema,
  register(registry, ctx) {
    registry.store(new FileStore(path.join(ctx.paths.state, ctx.config.directory), !ctx.readOnly));
  },
});
